package com.termux.app.workspace;

import android.app.*;import android.widget.*;
import com.termux.app.TermuxActivity;import com.termux.shared.termux.TermuxConstants;import com.termux.shared.shell.TermuxShellUtils;
import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.function.*;

/** User-triggered rootfs operations. No live-session switching or shell injection. */
final class AgentEnvironmentManager implements AutoCloseable {
    static final Set<String> operating=ConcurrentHashMap.newKeySet();
    private final TermuxActivity activity;private final WorkspaceStore store;private final Predicate<String> live;
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private boolean closed;
    private AlertDialog progress;private volatile File cancelFile;
    AgentEnvironmentManager(TermuxActivity a,WorkspaceStore s,Predicate<String> running){activity=a;store=s;live=running;}
    String t(String r,String e){return WorkspaceLanguage.code(activity).equals("ru")?r:e;}
    static boolean busy(WorkspaceStore.Session p){return operating.contains(AgentEnvironments.scope(p));}
    List<String> references(String alias){List<String> names=new ArrayList<>();for(WorkspaceStore.Session p:store.sessions)if((p.saved||!p.handle.isEmpty())&&alias.equals(AgentEnvironments.scope(p)))names.add(p.name);return names;}
    private boolean running(String alias){return live.test(alias);}
    private void message(String value){if(!closed)WorkspaceDialogs.builder(activity).setMessage(value).setPositiveButton(t("Назад","Back"),null).show();}
    Consumer<Consumer<Boolean>> freshInstall,prepareTools;
    void choose(String current,Consumer<String> selected){
        WorkspaceDialogs.builder(activity).setTitle(t("Окружение агента","Agent environment")).setSingleChoiceItems(new String[]{"Ubuntu",t("Ubuntu AI · для агентов","Ubuntu AI · for agents")},current.equals("ubuntu-ai")?1:0,(d,w)->{
            String alias=w==0?"ubuntu":"ubuntu-ai";d.dismiss();
            selected.accept(alias);
        }).setNegativeButton(t("Назад","Back"),null).show();
    }
    void migrate(Consumer<String> selected){
        File proot=new File(TermuxConstants.TERMUX_PREFIX_DIR_PATH,"var/lib/proot-distro");if(WorkspaceEnvironments.root(proot,"ubuntu")==null&&WorkspaceEnvironments.root(proot,"ubuntu-ai")==null&&freshInstall!=null){freshInstall.accept(ok->{if(ok)selected.accept("ubuntu-ai");});return;}
        if(running("ubuntu")||running("ubuntu-ai")){message(t("Сначала закройте все сессии и рабочий стол исходной Ubuntu. Активная среда не копируется. Работающие сессии автоматически не останавливаются.","Close all sessions and the desktop using the source Ubuntu first. A live environment is not copied. Running sessions are never stopped automatically."));return;}
        if(WorkspaceEnvironments.root(new File(TermuxConstants.TERMUX_PREFIX_DIR_PATH,"var/lib/proot-distro"),"ubuntu-ai")!=null){message(t("Ubuntu AI уже существует. Её файлы не будут перезаписаны. Выберите её в окружении агента.","Ubuntu AI already exists. Its files will not be overwritten. Select it in the agent environment."));return;}
        run("plan","ubuntu","prepare-migration",true,plan->{
            long bytes=plan.optLong("bytes"),free=plan.optLong("free");String token=plan.optString("token");
            String body=t("Ubuntu → Ubuntu AI\nБудет скопирована вся файловая система Ubuntu: проекты, файлы, инструменты, история, ключи, пароли и настройки. Секреты останутся в обеих системах. Общая память телефона и другие подключённые извне каталоги не копируются. Android-каталоги /apex, /data/app, /data/dalvik-cache и другие служебные точки подключения исключены заранее; в копии сохраняются пустые каталоги. Служебные подключения сессий и агентов в /tmp также не копируются; пресеты и история в приложении сохраняются. Системы не синхронизируются. Жёстко прописанные пути в скриптах могут потребовать корректировки.\n\n","Ubuntu → Ubuntu AI\nCopy the entire Ubuntu filesystem: projects, files, tools, history, keys, passwords and settings. Secrets remain in both systems. Phone shared storage and other external mounts are not copied. Android /apex, /data/app, /data/dalvik-cache and other host mount points are excluded in advance; directory placeholders are retained. Session and agent service mounts in /tmp are also excluded; app presets and history are retained. The systems do not synchronize. Hardcoded paths in scripts may need adjustment.\n\n")+t("Объём: ","Size: ")+size(bytes)+t("\nСвободно: ","\nFree: ")+size(free)+t("\nИсходная Ubuntu сохраняется. Нужен запас 256 МиБ. Во время копирования не запускайте её вручную.","\nThe source Ubuntu is retained. An extra 256 MiB is required. Do not start it manually during copying.");
            if(plan.optBoolean("emptyWorkspaceRemoved"))body+="\n\n"+t("Подготовка: удалён только пустой /workspace с правами 000. Файлы не удалялись.","Preparation removed only an empty mode000 /workspace directory. No files were deleted.");
            AlertDialog confirm=WorkspaceDialogs.builder(activity).setTitle(t("Миграция среды агента","Agent environment migration")).setMessage(body).setNegativeButton(t("Назад","Back"),null).setPositiveButton(t("Копировать","Copy"),(d,w)->{
                if(running("ubuntu")||running("ubuntu-ai")){message(error("ENVIRONMENT_BUSY"));return;}
                run("clone","ubuntu",token,true,result->{
                    WorkspaceDialogs.builder(activity).setTitle(t("Ubuntu AI создана и проверена","Ubuntu AI created and verified"))
                        .setMessage(t("Исходная Ubuntu сохранена. Выберите, какие настройки переключить. Текущая форма сохраняется обычной кнопкой сохранения/запуска. Другие файлы приложения и данные общей памяти не переносились.","The source Ubuntu is retained. Choose which settings to switch. Save the current form with the usual save/launch button. Other app files and shared storage were not moved."))
                        .setPositiveButton(t("Эту сессию / пресет","This session / preset"),(x,y)->selected.accept("ubuntu-ai"))
                        .setNeutralButton(t("Все агентские пресеты","All agent presets"),(x,y)->{if(!store.isWritable()){message(t("Библиотека недоступна для записи","Library is not writable"));return;}for(WorkspaceStore.Session p:store.sessions)if(!AgentPreparation.agent(p).isEmpty()&&p.codexEnvironment.equals("ubuntu")&&!running(AgentEnvironments.scope(p)))p.codexEnvironment="ubuntu-ai";store.save();selected.accept("ubuntu-ai");})
                        .setNegativeButton(t("Позже","Later"),null).show();
                });
            }).create();confirm.setCanceledOnTouchOutside(false);confirm.show();confirm.getButton(-1).setEnabled(free>=bytes+256L*1024*1024);
        });
    }
    void remove(WorkspaceEnvironments.Choice choice,Runnable refresh){
        String alias=choice.alias;if(alias.isEmpty()||!WorkspaceLocalFilePicker.validAlias(alias)||!choice.installed)return;
        if(running(alias)){message(error("ENVIRONMENT_BUSY"));return;}
        List<String> refs=references(alias);if(!refs.isEmpty()){message(t("Окружение используется сессиями или пресетами. Сначала переключите их на другую среду либо удалите пресеты:\n• ","The environment is referenced by sessions or presets. Switch them to another environment or remove those presets first:\n• ")+String.join("\n• ",refs));return;}
        run("plan",alias,"",true,plan->{
            AlertDialog confirm=WorkspaceDialogs.builder(activity).setTitle(t("Удалить ","Delete ")+choice.label+"?")
                .setMessage(t("Навсегда удалятся все файлы, проекты, пакеты, ключи и настройки этого окружения.\n","Permanently delete all files, projects, packages, keys and settings in this environment.\n")+choice.alias+" · "+size(plan.optLong("bytes"))+t("\nАрхивы резервных копий и общая память телефона сохраняются. Произвольные команды со вписанным вручную именем системы автоматически не распознаются. Отменить начавшееся удаление нельзя.","\nBackup archives and phone shared storage are retained. Arbitrary commands containing a manually typed system name are not detected automatically. Deletion cannot be cancelled once started."))
                .setNegativeButton(t("Назад","Back"),null).setPositiveButton(t("Удалить навсегда","Delete permanently"),(d,w)->{if(running(alias)||!references(alias).isEmpty()){message(error("ENVIRONMENT_BUSY"));return;}run("remove",alias,plan.optString("token"),false,result->refresh.run());}).create();confirm.setCanceledOnTouchOutside(false);confirm.show();
        });
    }
    private String size(long b){return android.text.format.Formatter.formatShortFileSize(activity,b);}
    private void problem(String code,Runnable retry){
        if((code.equals("MIGRATION_TOOLS_REQUIRED")||code.equals("NATIVE_LOCKS_REQUIRED"))&&prepareTools!=null){WorkspaceDialogs.builder(activity).setMessage(error(code)).setNegativeButton(t("Назад","Back"),null).setPositiveButton(t("Подготовить автоматически","Prepare automatically"),(d,w)->prepareTools.accept(ok->{if(ok&&!closed)retry.run();})).show();}else message(error(code));
    }
    private void run(String op,String alias,String token,boolean cancellable,Consumer<JSONObject> done){
        if(closed)return;
        if(op.equals("remove")&&(running(alias)||!references(alias).isEmpty())){message(error("ENVIRONMENT_BUSY"));return;}
        if(!new File(TermuxConstants.TERMUX_BIN_PREFIX_DIR_PATH,"python3").canExecute()||!new File(TermuxConstants.TERMUX_BIN_PREFIX_DIR_PATH,"proot-distro").canExecute()){problem("MIGRATION_TOOLS_REQUIRED",()->run(op,alias,token,cancellable,done));return;}
        Set<String> scopes=new HashSet<>();scopes.add(alias);if(op.equals("clone"))scopes.add("ubuntu-ai");
        synchronized(operating){for(String s:scopes)if(operating.contains(s)){message(error("ENVIRONMENT_BUSY"));return;}operating.addAll(scopes);}
        LinearLayout body=new LinearLayout(activity);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(24,16,24,16);ProgressBar bar=new ProgressBar(activity,null,android.R.attr.progressBarStyleHorizontal);bar.setIndeterminate(true);body.addView(bar);TextView status=new TextView(activity);status.setTextColor(WorkspaceDialogs.TEXT);status.setText(token.equals("prepare-migration")?t("Подготовка и проверка. Только пустой /workspace с правами 000 может быть удалён автоматически; файлы не удаляются.","Preparing and checking. Only an empty mode000 /workspace directory may be removed automatically; no files are deleted."):t("Проверка…","Checking…"));body.addView(status);
        AlertDialog wait=WorkspaceDialogs.builder(activity).setTitle(op.equals("remove")?t("Удаление окружения","Deleting environment"):op.equals("plan")?t("Сканирование окружения","Scanning environment"):t("Миграция среды агента","Agent environment migration")).setView(body).setNegativeButton(cancellable?t("Отмена","Cancel"):t("Назад","Back"),null).create();progress=wait;wait.setCancelable(false);wait.setCanceledOnTouchOutside(false);wait.show();wait.getButton(-2).setEnabled(cancellable);
        final java.util.concurrent.atomic.AtomicBoolean stop=new java.util.concurrent.atomic.AtomicBoolean();wait.getButton(-2).setOnClickListener(v->{stop.set(true);File f=cancelFile;if(f!=null)try{f.createNewFile();}catch(IOException ignored){}wait.getButton(-2).setEnabled(false);status.setText(t("Отмена и очистка незавершённой копии…","Cancelling and cleaning the incomplete copy…"));});
        worker.execute(()->{JSONObject result=null;String failure="OPERATION_FAILED",location="";File marker=null;Process child=null;
            try{
                File dir=new File(activity.getFilesDir(),".agent-migration");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException();
                if(!dir.getCanonicalFile().equals(new File(activity.getFilesDir().getCanonicalFile(),".agent-migration")))throw new IOException();
                protect(dir);
                File script=new File(dir,"runtime.py"),temp=File.createTempFile("runtime-",".tmp",dir);
                try{try(InputStream in=activity.getAssets().open("agent-environment.py");OutputStream out=new FileOutputStream(temp)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}protect(temp);if(!temp.renameTo(script))throw new IOException();}finally{temp.delete();}
                marker=new File(dir,"cancel-"+UUID.randomUUID());cancelFile=marker;if(stop.get()||closed)marker.createNewFile();
                ProcessBuilder pb=new ProcessBuilder(TermuxConstants.TERMUX_BIN_PREFIX_DIR_PATH+"/python3",script.getAbsolutePath(),op,alias,token,marker.getAbsolutePath());pb.environment().clear();for(String v:TermuxShellUtils.buildEnvironment(activity,false,TermuxConstants.TERMUX_HOME_DIR_PATH)){int eq=v.indexOf('=');if(eq>0)pb.environment().put(v.substring(0,eq),v.substring(eq+1));}pb.environment().put("PREFIX",TermuxConstants.TERMUX_PREFIX_DIR_PATH);pb.environment().put("PYTHONDONTWRITEBYTECODE","1");pb.redirectError(new File("/dev/null"));Process p=pb.start();child=p;p.getOutputStream().close();
                try(BufferedReader reader=new BufferedReader(new InputStreamReader(p.getInputStream(),StandardCharsets.UTF_8))){String line;while((line=reader.readLine())!=null){if(line.length()>8192)throw new IOException();JSONObject event=new JSONObject(line);String kind=event.optString("event");if(kind.equals("progress")){activity.runOnUiThread(()->{if(closed||progress!=wait||!wait.isShowing())return;long total=event.optLong("total"),value=event.optLong("done");bar.setIndeterminate(total<=0);if(total>0){bar.setMax(1000);bar.setProgress((int)Math.min(1000,value*1000/total));}String phase=event.optString("phase");status.setText((phase.equals("copy")?t("Копирование","Copying"):phase.equals("verify")?t("Проверка файлов","Verifying files"):phase.equals("publish")?t("Завершение","Finishing"):t("Сканирование","Scanning"))+"\n"+size(value)+(total>0?" / "+size(total):""));});}else if(kind.equals("error")){failure=event.optString("code","OPERATION_FAILED")+(event.has("errno")?"_ERRNO_"+event.optInt("errno"):"");location=scanDetails(event);}else if(kind.equals("plan")||kind.equals("done"))result=event;}}
                if(p.waitFor()!=0)result=null;
            }catch(Exception ignored){}finally{if(child!=null&&child.isAlive()){if(marker!=null)try{marker.createNewFile();}catch(IOException ignored){}try{child.waitFor();}catch(InterruptedException e){Thread.currentThread().interrupt();}}if(marker!=null)marker.delete();cancelFile=null;synchronized(operating){operating.removeAll(scopes);}}
            JSONObject answer=result;String reason=failure,detail=location;activity.runOnUiThread(()->{if(progress==wait)progress=null;wait.dismiss();if(closed)return;if(stop.get()&&op.equals("plan")){message(error("CANCELLED"));return;}if(answer==null){if(detail.isEmpty())problem(reason,()->run(op,alias,token,cancellable,done));else message(error(reason)+detail);}else done.accept(answer);});
        });
    }
    private static void protect(File f)throws IOException{if(!f.setReadable(false,false)||!f.setWritable(false,false)||!f.setExecutable(false,false)||!f.setReadable(true,true)||!f.setWritable(true,true)||f.isDirectory()&&!f.setExecutable(true,true))throw new IOException("Private permissions unavailable");}
    String scanDetails(JSONObject event){
        if(!event.optString("code").equals("SCAN_ACCESS_DENIED")||!event.has("scanPath"))return "";
        String path=event.optString("scanPath"),op=event.optString("scanOperation");
        if(path.startsWith("/")||Arrays.asList(path.split("/",-1)).contains("..")||!Arrays.asList("list","stat","open-directory").contains(op))return "";
        StringBuilder safe=new StringBuilder();for(int i=0;i<Math.min(path.length(),2048);i++){char c=path.charAt(i);if(Character.isISOControl(c)||(c>=0x202a&&c<=0x202e)||(c>=0x2066&&c<=0x2069))safe.append(String.format(Locale.ROOT,"\\u%04x",(int)c));else safe.append(c);}if(path.length()>2048)safe.append("…");
        String action=op.equals("list")?t("чтение списка каталога","listing directory"):op.equals("stat")?t("чтение атрибутов","reading metadata"):t("открытие каталога","opening directory");
        return "\n\n"+t("Операция: ","Operation: ")+action+"\n"+t("Путь внутри исходного контейнера: ","Path inside source container: ")+(path.isEmpty()?t("корень контейнера","container root"):safe.toString())+"\n"+t("Версия проверки: ","Diagnostic version: ")+com.termux.BuildConfig.VERSION_NAME;
    }
    String error(String code){
        if(code.contains("_ERRNO_")){String[] parts=code.split("_ERRNO_",2);return error(parts[0])+"\n"+t("Системный код: ","System code: ")+parts[1];}
        switch(code){case "MIGRATION_TOOLS_REQUIRED":return t("В Termux отсутствует Python или proot-distro. Можно подготовить необходимые компоненты автоматически.","Python or proot-distro is missing in Termux. Required components can be prepared automatically.");
        case "STORAGE_ACCESS_DENIED":return t("Android отказал в доступе к пути хранилища proot-distro. Это ошибка доступа, а не признак отсутствия пакетов. Код: STORAGE_ACCESS_DENIED", "Android denied access to the proot-distro storage path. This is an access failure, not evidence of missing packages. Code: STORAGE_ACCESS_DENIED");
        case "PROCESS_CHECK_DENIED":return t("Android не разрешил проверить процессы. Без проверки занятости миграция не запускается. Код: PROCESS_CHECK_DENIED", "Android denied process inspection. Migration cannot start without the busy check. Code: PROCESS_CHECK_DENIED");
        case "ENVIRONMENT_PATH_MISSING":return t("Не найден путь исходного окружения в containers либо обязательный файл системы. Нужна проверка структуры среды. Код: ENVIRONMENT_PATH_MISSING", "The source containers environment path or a required system file is missing. Check the environment layout. Code: ENVIRONMENT_PATH_MISSING");
        case "LOCKS_ACCESS_DENIED":return t("Нет доступа к каталогу или файлу блокировки proot-distro. Файлы Ubuntu ещё не сканировались. Код: LOCKS_ACCESS_DENIED","Access to the proot-distro lock directory or file was denied. Ubuntu files have not been scanned. Code: LOCKS_ACCESS_DENIED");
        case "SCAN_ACCESS_DENIED":return t("Отказ при сканировании каталогов или атрибутов файлов Ubuntu. Содержимое ключей на этом этапе не читается. Код: SCAN_ACCESS_DENIED","Access denied while scanning Ubuntu directories or file metadata. Key contents are not read at this stage. Code: SCAN_ACCESS_DENIED");
        case "ENVIRONMENT_ACCESS_DENIED":return t("Нет доступа к структуре каталогов окружения. Код: ENVIRONMENT_ACCESS_DENIED","Access to the environment directory structure was denied. Code: ENVIRONMENT_ACCESS_DENIED");
        case "COPY_ACCESS_DENIED":return t("Отказ в доступе при копировании или проверке файлов. Исходная Ubuntu сохранена. Код: COPY_ACCESS_DENIED","Access denied during file copying or verification. The source Ubuntu is retained. Code: COPY_ACCESS_DENIED");
        case "FILES_ACCESS_DENIED":return t("Нет доступа к одному из файлов или каталогов окружения. Установка пакетов не предлагается, так как причина в доступе. Код: FILES_ACCESS_DENIED", "An environment file or directory is inaccessible. Package installation is not suggested for an access failure. Code: FILES_ACCESS_DENIED");
        case "FILESYSTEM_ERROR":return t("Файловая операция завершилась ошибкой; системный код приведён ниже. Код: FILESYSTEM_ERROR", "Filesystem operation failed; see the system code below. Code: FILESYSTEM_ERROR");case "CANCELLED":return t("Отменено. Исходная среда сохранена; незавершённая копия удалена.","Cancelled. The source is retained; the incomplete copy was removed.");case "ENVIRONMENT_BUSY":return t("Среда занята. Закройте её сессии, рабочий стол и пакетные операции, затем повторите. Процессы автоматически не останавливаются.","Environment busy. Close its sessions, desktop and package operations, then retry. Processes are not stopped automatically.");case "SOURCE_CHANGED":return t("Файлы среды изменились. Повторите сканирование при закрытых сессиях.","Environment files changed. Scan again with sessions closed.");case "DESTINATION_EXISTS":return t("Ubuntu AI уже существует; перезапись запрещена.","Ubuntu AI already exists; overwriting is refused.");case "NATIVE_LOCKS_REQUIRED":return t("Нужен proot-distro 5 с блокировками и хранилищем containers. Обновите пакет proot-distro в Termux и повторите. Старые среды не изменены.","Requires proot-distro 5 with locks and containers storage. Update proot-distro in Termux and retry. Existing systems are unchanged.");case "DELETE_INCOMPLETE":return t("Удаление завершилось ошибкой и могло удалить часть файлов. Остаток находится в скрытом служебном каталоге .jobs-delete-* внутри хранилища proot-distro. Другие окружения не удалялись.","Deletion failed and may have removed some files. The remainder is in a hidden .jobs-delete-* service directory in proot-distro storage. Other systems were not removed.");case "UNSUPPORTED_SPECIAL_FILE":return t("В среде есть специальный файл, который нельзя безопасно скопировать. Перенос остановлен; исходная система сохранена.","The system contains a special file which cannot be safely copied. Migration stopped; the source is retained.");case "NOT_ENOUGH_SPACE":return t("Недостаточно свободного места для полной копии и запаса 256 МиБ.","Not enough free storage for the full copy plus 256 MiB reserve.");default:return t("Операция не завершена. Исходная Ubuntu не удаляется при миграции. Не удалось определить точный этап сбоя. Код: ","Operation incomplete. Migration never deletes the source Ubuntu. The exact failing stage could not be determined. Code: ")+code;}}
    public void close(){closed=true;File f=cancelFile;if(f!=null)try{f.createNewFile();}catch(IOException ignored){}if(progress!=null)progress.dismiss();worker.shutdown();}
}
